const categoryData=[{name:'Shoes',icon:'👟',href:'https://findspreadsheet.com/shoes/',copy:'Explore footwear listings in one focused category view. Compare visible item details and keep a shortlist before you move on.'},{name:'T-Shirts',icon:'👕',href:'https://findspreadsheet.com/AllProducts/',copy:'Use the T-Shirts category to narrow a broad product search into a more useful, repeatable research path.'},{name:'Hoodies',icon:'🧥',href:'https://findspreadsheet.com/hoodies-sweaters/',copy:'A direct category route for hoodies and sweaters, designed for checking listing cues and variants with less noise.'},{name:'Jackets',icon:'🥼',href:'https://findspreadsheet.com/AllProducts/',copy:'Browse jacket-related listings from the live database, then compare the product details that matter to you.'},{name:'Pants',icon:'👖',href:'https://findspreadsheet.com/AllProducts/',copy:'Start with pants to make your research more specific, then use the live database for the available product routes.'},{name:'Bags',icon:'👜',href:'https://findspreadsheet.com/AllProducts/',copy:'A clean entry point for bag listings. Check visible variations and compare alternatives at FindSpreadsheet.'},{name:'Jerseys',icon:'⚽',href:'https://findspreadsheet.com/AllProducts/',copy:'The jersey category groups a focused research path before you continue to the live product database.'},{name:'Accessories',icon:'⌚',href:'https://findspreadsheet.com/AllProducts/',copy:'Explore accessories through a defined category rather than an open-ended product feed.'},{name:'Electronics',icon:'🎧',href:'https://findspreadsheet.com/electronics/',copy:'Use this direct route for electronics listings and retain a clear comparison frame while you browse.'},{name:'Other Stuff',icon:'📦',href:'https://findspreadsheet.com/AllProducts/',copy:'For items outside the main groups, this category keeps the discovery route simple and direct.'}];
