/* Use a native select so the language control is dependable on desktop and mobile. */
(()=>{
  const languageList=[['en','English'],['es','Español'],['fr','Français'],['de','Deutsch'],['it','Italiano'],['pt','Português'],['nl','Nederlands'],['pl','Polski'],['sv','Svenska']];
  const languageCodes=new Set(languageList.map(([code])=>code));
  const pathParts=location.pathname.split('/').filter(Boolean);
  const pathLanguage=languageCodes.has(pathParts[0])?pathParts[0]:'en';
  const pagePath=(pathLanguage==='en'?pathParts:pathParts.slice(1)).join('/')||'index.html';
  const legacyLanguage=new URLSearchParams(location.search).get('lang');
  const current=pathLanguage;
  const localizedPath=(code,path=pagePath)=>code==='en'?'/'+path:'/'+code+'/'+path;
  /* Upgrade old ?lang= links once, then always use a real language-specific URL. */
  if(pathLanguage==='en'&&languageCodes.has(legacyLanguage)&&legacyLanguage!=='en'){
    const target=new URL(location.href);
    target.pathname=localizedPath(legacyLanguage);
    target.searchParams.delete('lang');
    location.replace(target.pathname+target.search+target.hash);
    return;
  }
  const translateText=async(text,code)=>{
    const response=await fetch('https://translate.googleapis.com/translate_a/single?client=gtx&sl=en&tl='+encodeURIComponent(code)+'&dt=t&q='+encodeURIComponent(text));
    if(!response.ok)throw new Error('translation unavailable');
    const data=await response.json();
    return data[0].map(part=>part[0]).join('');
  };
  const languageName=code=>languageList.find(([id])=>id===code)?.[1]||'English';
  const createMenu=()=>{
    const menu=document.createElement('details');
    menu.className='language-menu';
    menu.innerHTML='<summary aria-label="Choose language"><span class="language-globe" aria-hidden="true">◎</span><span class="language-current">'+current.toUpperCase()+'</span><span class="language-chevron" aria-hidden="true">⌄</span></summary><div class="language-options" role="menu" aria-label="Choose language">'+languageList.map(([code,name])=>'<a href="'+localizedPath(code)+'" data-language="'+code+'" role="menuitem" aria-current="'+(code===current?'true':'false')+'"><span>'+code.toUpperCase()+'</span><b>'+name+'</b><i aria-hidden="true">'+(code===current?'✓':'')+'</i></a>').join('')+'</div>';
    return menu;
  };
  document.querySelectorAll('.masthead .database').forEach(link=>link.replaceWith(createMenu()));
  const menus=[...document.querySelectorAll('.language-menu')];
  const syncMenus=code=>menus.forEach(menu=>{
    menu.querySelector('.language-current').textContent=code.toUpperCase();
    menu.querySelector('summary').setAttribute('aria-label','Language: '+languageName(code));
    menu.querySelectorAll('[data-language]').forEach(button=>{const selected=button.dataset.language===code;button.setAttribute('aria-current',String(selected));button.querySelector('i').textContent=selected?'✓':'';});
  });
  const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,{acceptNode:node=>{
      const parent=node.parentElement;
      if(!node.nodeValue.trim()||!parent||parent.closest('script,style,.language-menu'))return NodeFilter.FILTER_REJECT;
      return NodeFilter.FILTER_ACCEPT;
    }});
  const textNodes=[];let node;while(node=walker.nextNode())textNodes.push({node,original:node.nodeValue});
  const paint=(words,code)=>{textNodes.forEach((item,index)=>{item.node.nodeValue=words[index]});document.documentElement.lang=code;};
  const translatePage=async code=>{
    if(code==='en'){paint(textNodes.map(item=>item.original),'en');return;}
    const words=new Array(textNodes.length);
    for(let index=0;index<textNodes.length;index+=24){await Promise.all(textNodes.slice(index,index+24).map(async(item,offset)=>{try{words[index+offset]=await translateText(item.original,code)}catch{words[index+offset]=item.original;}}));}
    paint(words,code);
  };
  menus.forEach(menu=>{
    menu.addEventListener('toggle',()=>{if(menu.open)menus.forEach(other=>{if(other!==menu)other.open=false;});});
    menu.addEventListener('keydown',event=>{if(event.key==='Escape')menu.open=false;});
  });
  document.addEventListener('click',event=>menus.forEach(menu=>{if(menu.open&&!menu.contains(event.target))menu.open=false;}));
  document.querySelectorAll('a[href]').forEach(link=>{
    if(link.closest('.language-menu'))return;
    const target=new URL(link.href,location.href);
    if(target.origin!==location.origin||!target.pathname.endsWith('.html'))return;
    const parts=target.pathname.split('/').filter(Boolean);
    const equivalentPath=(languageCodes.has(parts[0])?parts.slice(1):parts).join('/')||'index.html';
    target.pathname=localizedPath(current,equivalentPath);
    target.searchParams.delete('lang');
    link.href=target.pathname+target.search+target.hash;
  });
  if(current!=='en'){
    syncMenus(current);
    translatePage(current);
  }
  document.querySelectorAll('a').forEach(link=>{if(/database/i.test(link.textContent))link.href='https://findspreadsheet.com/';});
  document.addEventListener('submit',event=>{const form=event.target;if(form?.id!=='site-search')return;event.preventDefault();event.stopImmediatePropagation();const term=form.q.value.trim();if(term)window.location.assign(findSpreadsheetSearch(term));},true);
  document.head.insertAdjacentHTML('beforeend','<style>.masthead{position:sticky!important;top:0}.language-menu{position:relative;z-index:60;flex:0 0 auto}.language-menu summary{display:flex;align-items:center;justify-content:center;gap:7px;min-width:94px;min-height:42px;padding:0 13px;border:3px solid #f7d0a1;border-radius:999px;background:#4c2410;color:#fff;cursor:pointer;font:800 12px/1 ui-monospace,SFMono-Regular,Menlo,monospace;letter-spacing:.06em;list-style:none;box-shadow:0 0 0 2px #fffaf5;user-select:none}.language-menu summary::-webkit-details-marker{display:none}.language-menu summary:focus{outline:3px solid rgba(223,113,7,.32);outline-offset:2px}.language-globe{font:700 18px/1 Arial}.language-chevron{font-size:16px;line-height:1;transition:transform .18s ease}.language-menu[open] summary{background:#633016}.language-menu[open] .language-chevron{transform:rotate(180deg)}.language-options{position:absolute;right:0;top:calc(100% + 8px);display:grid;grid-template-columns:1fr 1fr;gap:4px;width:238px;padding:8px;border:1px solid #ead6bf;border-radius:14px;background:#fffaf5;box-shadow:0 18px 38px rgba(76,36,16,.2)}.language-options a{display:grid;grid-template-columns:25px 1fr 13px;align-items:center;min-height:35px;padding:0 7px;border:0;border-radius:8px;background:transparent;color:#4c2410;cursor:pointer;text-align:left;font:600 12px/1.1 system-ui,sans-serif;text-decoration:none}.language-options a span{font:800 10px/1 ui-monospace,SFMono-Regular,Menlo,monospace;color:#9c5732}.language-options a i{font-style:normal;color:#e87500}.language-options a:hover,.language-options a:focus-visible,.language-options a[aria-current="true"]{background:#f1dfca;outline:0}.language-menu.is-switching{pointer-events:none;opacity:.72}@media(max-width:760px){.language-menu summary{min-width:62px;min-height:38px;padding:0 9px;gap:5px;font-size:11px}.language-globe{font-size:16px}.language-chevron{display:none}.language-options{right:-2px;grid-template-columns:1fr;width:182px}.language-options a{min-height:34px;font-size:13px}}@media(min-width:521px){.hero{min-height:0!important}.hero>div:first-child{padding:42px 0 34px!important}.hero h1{font-size:clamp(56px,6.1vw,82px)!important;line-height:.82!important;margin:18px 0!important}.lede{font-size:18px!important}.site-search{margin-top:22px!important}}</style>');
  document.head.insertAdjacentHTML('beforeend','<style>@media(min-width:761px){.category-detail{min-height:390px!important;margin:40px 0!important}.category-detail-copy,.category-detail-action{padding:40px!important}.category-detail-copy h1{margin:20px 0!important;font-size:clamp(54px,7vw,88px)!important}.category-detail-copy p{font-size:18px!important}.category-detail-action h2{margin:24px 0 14px!important;font-size:clamp(38px,4.5vw,58px)!important}.category-detail-action p{font-size:17px!important}.category-detail-action .button{margin-top:20px!important}}</style>');
  document.head.insertAdjacentHTML('beforeend','<style>@media(min-width:521px){.hero>div:first-child{padding-left:3cm!important}}</style>');
})();
